<?php require '_auth.php';if(isset($_GET['delete'])){$pdo->prepare("DELETE FROM messages WHERE id=?")->execute([(int)$_GET['delete']]);header('Location:messages.php');exit;}$adminTitle='Messages';$rows=$pdo->query("SELECT * FROM messages ORDER BY id DESC")->fetchAll();include '_header.php';?><section class="panel"><div class="panel-head"><h2>Customer messages</h2></div><table class="table"><tr><th>From</th><th>Subject</th><th>Message</th><th>Date</th><th></th></tr><?php foreach($rows as $m):?><tr><td><?=e($m['name'])?><br><small><?=e($m['email'])?></small></td><td><?=e($m['subject'])?></td><td><?=e($m['message'])?></td><td><?=e($m['created_at'])?></td><td><a class="btn red" href="messages.php?delete=<?=$m['id']?>">Delete</a></td></tr><?php endforeach;?></table></section><?php include '_footer.php';?>
